if (!window.__qStepPop) { window.__qStepPop = true; window.addEventListener('popstate', () => window.setTimeout(() => document.querySelector('.q-step-frame > .q-step-pop')?.click(), 0)); }window.requestAnimationFrame(() => window.requestAnimationFrame(() => {const box = document.querySelector("main.q-panel"); if (box) box.scrollTo({top: 0});const h = document.querySelector("main.q-panel .q-step-title"); if (h) h.focus({preventScroll: true});}));window.requestAnimationFrame(() => window.requestAnimationFrame(() => {if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;const panel=document.querySelector('.q-menu-guided-panel');if(!panel)return;const style=getComputedStyle(panel);const raw=style.getPropertyValue('--q-dur-slow').trim();const duration=(parseFloat(raw)||380)*(raw.endsWith('ms')?1:raw.endsWith('s')?1000:1);const x=panel.dataset.dir==='back'?-8:8;panel.getAnimations().forEach(a=>a.cancel());panel.animate([{transform:'translateX('+x+'px)'},{transform:'none'}],{duration,easing:style.getPropertyValue('--q-ease').trim()||'ease',fill:'both'});}));